#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-04

# =============================================================================
# Duplicate Living-Plan Detector
# =============================================================================
# The living-plan contract is "one plan = ONE file". Detection used to key on
# docs/<branch-dir>/plan-viz.html — a path derived from the branch name. Rename
# the branch and the check misses, so the next session authors a SECOND file for
# the same plan and the two drift apart with no merge path.
#
# That is not hypothetical. Slug "langchain-ecosystem-currency" existed twice,
# same `updated` date, under docs/chore--… and docs/research--…, and nothing in
# the suite noticed. Detection is now slug-keyed
# (src/skills/visualize-plan/scripts/find-living-plan.sh); this test is the gate
# that keeps it honest.
#
# Severity split, deliberate:
#   TRACKED duplicates   -> FAIL. A committed fork is a shipped defect.
#   Untracked duplicates -> WARN. Local scratch; noisy to block a whole test run on.
# Set DUPLICATE_PLANS_STRICT=1 to fail on untracked duplicates too.
#
# Also checks the filename convention: the spec says plan-viz.html, and reality
# ran 5:1 against it (index.html x79 vs plan-viz.html x18). Advisory — existing
# artifacts are grandfathered; set DUPLICATE_PLANS_FILENAME_ENFORCE=1 to gate.
# =============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
cd "$REPO_ROOT"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; YELLOW=$'\033[1;33m'
BLUE=$'\033[0;34m'; BOLD=$'\033[1m'; NC=$'\033[0m'

STRICT="${DUPLICATE_PLANS_STRICT:-0}"
FILENAME_ENFORCE="${DUPLICATE_PLANS_FILENAME_ENFORCE:-0}"

echo "${BLUE}${BOLD}Duplicate living-plan detector (one plan = one file)${NC}"

if [[ ! -d docs ]]; then
    echo "${GREEN}✓ No docs/ directory — nothing to check${NC}"
    exit 0
fi

# --- collect "<slug>\t<path>" for every living plan in the working tree --------
# grep exit 1 = no living plans at all, which is a pass. Anything >1 is a real error.
candidates=""
grep_rc=0
candidates="$(grep -rl 'id="lpp-state"' docs --include='*.html')" || grep_rc=$?
if (( grep_rc > 1 )); then
    echo "${RED}✗ grep failed (exit $grep_rc) scanning docs/${NC}" >&2
    exit 1
fi
if [[ -z "$candidates" ]]; then
    echo "${GREEN}✓ No living plans found${NC}"
    exit 0
fi

pairs="$(
    while IFS= read -r f; do
        [[ -n "$f" ]] || continue
        case "$f" in */site/*) continue ;; esac   # generated docs site, not real plans
        python3 - "$f" <<'PY'
import json, re, sys
path = sys.argv[1]
try:
    text = open(path, encoding="utf-8", errors="replace").read()
except OSError as exc:
    print("READ_ERROR\t%s\t%s" % (path, exc), file=sys.stderr)
    sys.exit(0)
m = re.search(r'id="lpp-state"[^>]*>(.*?)</script>', text, re.S)
if not m:
    sys.exit(0)
try:
    slug = json.loads(m.group(1)).get("slug", "")
except ValueError as exc:
    print("MALFORMED\t%s\t%s" % (path, exc), file=sys.stderr)
    sys.exit(0)
if slug:
    print("%s\t%s" % (slug, path))
PY
    done < <(printf '%s\n' "$candidates")
)"

total=$(printf '%s\n' "$pairs" | sed '/^$/d' | wc -l | tr -d ' ')
echo "  scanned ${total} living plan(s)"

# --- group by slug, split tracked vs untracked --------------------------------
tracked_dupes=0
untracked_dupes=0

dupe_slugs="$(printf '%s\n' "$pairs" | sed '/^$/d' | cut -f1 | sort | uniq -d)"

if [[ -n "$dupe_slugs" ]]; then
    while IFS= read -r slug; do
        [[ -n "$slug" ]] || continue
        files="$(printf '%s\n' "$pairs" | awk -F'\t' -v s="$slug" '$1==s {print $2}' | sort)"
        n_tracked=0
        rendered=""
        while IFS= read -r f; do
            [[ -n "$f" ]] || continue
            # `git ls-files --error-unmatch` is a boolean probe: nonzero simply means
            # "not tracked", which is the answer we want, not an error to surface.
            if git ls-files --error-unmatch "$f" >/dev/null 2>&1; then
                n_tracked=$((n_tracked + 1))
                rendered+="      ${RED}tracked${NC}    $f"$'\n'
            else
                rendered+="      ${YELLOW}untracked${NC}  $f"$'\n'
            fi
        done < <(printf '%s\n' "$files")

        if (( n_tracked > 1 )); then
            tracked_dupes=$((tracked_dupes + 1))
            echo ""
            echo "  ${RED}✗ FORKED (committed):${NC} ${BOLD}${slug}${NC}"
        else
            untracked_dupes=$((untracked_dupes + 1))
            echo ""
            echo "  ${YELLOW}! forked (working tree):${NC} ${BOLD}${slug}${NC}"
        fi
        printf '%s' "$rendered"
    done < <(printf '%s\n' "$dupe_slugs")
fi

# --- filename convention (advisory) -------------------------------------------
badname=0
while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    p="${line#*$'\t'}"
    [[ "$(basename "$p")" == "plan-viz.html" ]] || badname=$((badname + 1))
done < <(printf '%s\n' "$pairs")

echo ""
echo "  ${GREEN}●${NC} slugs unique:            $(( total - tracked_dupes - untracked_dupes ))"
echo "  ${RED}●${NC} forked (committed):      ${tracked_dupes}"
echo "  ${YELLOW}●${NC} forked (working tree):   ${untracked_dupes}"
echo "  ${YELLOW}●${NC} not named plan-viz.html: ${badname}"
echo ""

fail=0
if (( tracked_dupes > 0 )); then
    echo "${RED}✗ ${tracked_dupes} plan slug(s) exist as more than one COMMITTED file.${NC}"
    echo "  Reconcile: pick the survivor, ${BOLD}git mv${NC} it into place, delete the other in the"
    echo "  same commit. Detect by slug before authoring:"
    echo "    ${BOLD}bash src/skills/visualize-plan/scripts/find-living-plan.sh <slug>${NC}"
    fail=1
fi

if (( untracked_dupes > 0 )); then
    echo "${YELLOW}! ${untracked_dupes} slug(s) forked in the working tree (not committed).${NC}"
    echo "  Set ${BOLD}DUPLICATE_PLANS_STRICT=1${NC} to treat these as failures."
    if [[ "$STRICT" == "1" ]]; then fail=1; fi
fi

if (( badname > 0 )); then
    echo "${YELLOW}! ${badname} living plan(s) are not named plan-viz.html.${NC}"
    echo "  Existing artifacts are grandfathered; new ones must use the canonical name."
    echo "  Set ${BOLD}DUPLICATE_PLANS_FILENAME_ENFORCE=1${NC} to gate on this."
    if [[ "$FILENAME_ENFORCE" == "1" ]]; then fail=1; fi
fi

if (( fail == 0 )); then
    echo "${GREEN}✓ No committed living-plan forks${NC}"
fi

exit "$fail"
